CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY, project TEXT NOT NULL, prompt TEXT NOT NULL, state TEXT NOT NULL, created_at TEXT NOT NULL, started_at TEXT, ended_at TEXT);
CREATE TABLE IF NOT EXISTS stages (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), stage_key TEXT NOT NULL, position INTEGER NOT NULL, state TEXT NOT NULL, provider TEXT NOT NULL, profile TEXT NOT NULL, model TEXT NOT NULL, effort TEXT NOT NULL, attempt INTEGER NOT NULL DEFAULT 1, UNIQUE(run_id, stage_key, attempt));
CREATE TABLE IF NOT EXISTS events (run_id TEXT NOT NULL REFERENCES runs(id), seq INTEGER NOT NULL, timestamp TEXT NOT NULL, stage TEXT, type TEXT NOT NULL, severity TEXT NOT NULL, payload_json TEXT NOT NULL, PRIMARY KEY(run_id,seq));
CREATE TABLE IF NOT EXISTS quality_gates (run_id TEXT NOT NULL REFERENCES runs(id), gate_key TEXT NOT NULL, verdict TEXT NOT NULL, evidence TEXT NOT NULL, PRIMARY KEY(run_id,gate_key));
CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, provider TEXT NOT NULL, executable TEXT NOT NULL, config_directory TEXT NOT NULL DEFAULT '', allowed_scopes_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, canonical_path TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, allowed_scopes_json TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS routing_decisions (run_id TEXT NOT NULL REFERENCES runs(id), stage TEXT NOT NULL, provider TEXT NOT NULL, profile TEXT NOT NULL, model TEXT NOT NULL, effort TEXT NOT NULL, policy TEXT NOT NULL, explanation TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(run_id,stage));
CREATE TABLE IF NOT EXISTS artifacts (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), stage TEXT NOT NULL, path TEXT NOT NULL, kind TEXT NOT NULL, sha256 TEXT NOT NULL, observed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS checkpoints (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), stage TEXT NOT NULL, state_json TEXT NOT NULL, workspace_fingerprint TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approvals (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), action TEXT NOT NULL, status TEXT NOT NULL, decision TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, resolved_at TEXT);
CREATE TABLE IF NOT EXISTS workspace_locks (canonical_path TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id), acquired_at TEXT NOT NULL);
